mapper.select:
SELECT id, recordIds, reason, borrowType, expectedReturnDate, status, submitTime, userId, userName, department, approver, approveTime, rejectionReason, returnTime, createdTime, updatedTime, deleted
FROM BorrowApplications
WHERE id = #{id}

mapper.update:
UPDATE BorrowApplications
SET status = #{status},
    updatedTime = #{updatedTime}
WHERE id = #{id}
  AND (deleted = 0 OR deleted IS NULL)
